import zipfile
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
}

def col_letter_to_idx(ref):
    letters = ''.join(c for c in ref if c.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - ord('A') + 1)
    return idx

def idx_to_col(idx):
    letters = ''
    while idx:
        idx, rem = divmod(idx - 1, 26)
        letters = chr(ord('A') + rem) + letters
    return letters

with zipfile.ZipFile("budget.xlsx") as z:
    print("=== Files in archive ===")
    for name in z.namelist():
        print(name)

    # Shared strings
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = ''.join(t.text or '' for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    # Workbook sheet list
    wbroot = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = []
    for sh in wbroot.find("m:sheets", NS):
        sheets.append((sh.get("name"), sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")))

    # Workbook rels
    relroot = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rels = {}
    for rel in relroot:
        rels[rel.get("Id")] = rel.get("Target")

    print()
    for name, rid in sheets:
        target = rels[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target
        print(f"=== Sheet: {name} ({target}) ===")
        sroot = ET.fromstring(z.read(target))
        for row in sroot.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row"):
            for c in row:
                if c.tag != "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c":
                    continue
                ref = c.get("r")
                t = c.get("t")
                v = c.find("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v")
                isel = c.find("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}is")
                val = None
                if t == "s" and v is not None:
                    val = shared[int(v.text)]
                elif t == "inlineStr" and isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                elif v is not None:
                    val = v.text
                print(f"{ref}: {val!r}")
        print()

